"""Ask Hermes node generated by aotn_node_helper."""

from typing import Any, ClassVar, Dict, List, Optional

from ...node_base import Node, NodeContext
from ...node_category import NodeCategory


class HermesAskNode(Node):
    """Ask one question using Hermes memory; returns text."""

    node_type: ClassVar[str] = 'hermes_ask_node'
    display_name: ClassVar[str] = 'Ask Hermes'
    default_alias: ClassVar[str] = 'Ask Hermes'
    description: ClassVar[str] = 'Ask one question using Hermes memory; returns text'
    category: ClassVar[str] = NodeCategory.AI
    primary_family: ClassVar[str] = 'Complex'
    tags: ClassVar[List[str]] = ['question', 'memory', 'agent']
    icon_name: ClassVar[str] = 'message-circle'
    color_hint: ClassVar[str] = 'violet'
    group: ClassVar[Optional[str]] = 'AI Processing'
    selector_section: ClassVar[Optional[str]] = 'AI'
    input_ports: ClassVar[List[str]] = ['input']
    output_ports: ClassVar[List[str]] = ['default', 'details']
    input_port_metadata: ClassVar[Dict[str, Dict[str, Any]]] = {'input': {'name': 'Question', 'description': '', 'data_type': 'string', 'required': True, 'sources': ['upstream', 'vault', 'configured']}}
    output_port_metadata: ClassVar[Dict[str, Dict[str, Any]]] = {'default': {'name': 'Answer', 'description': 'The final answer as text', 'data_type': 'string', 'required': True, 'to': ['downstream', 'vault'], 'pass_through': True}, 'details': {'name': 'Run details', 'description': 'Time, turns, token use, cost and saved record', 'data_type': 'var', 'required': False, 'to': ['vault']}}
    default_config: ClassVar[Dict[str, Any]] = {'input_source': 'Configured', 'input_vault_key': '', 'input': '', 'folder': '', 'timeout': 60, 'transient_output': True, 'dead_drop_passthrough': False, 'transient_outputs': [], 'vault_write': False, 'vault_write_key': '', 'vault_write_description': '', 'details_vault_write': False, 'details_vault_key': '', 'details_vault_description': ''}
    config_schema: ClassVar[Dict[str, Dict[str, Any]]] = {'input_source': {'type': 'select', 'label': 'Input source', 'options': ['Upstream payload', 'Vault', 'Configured'], 'tab': 'Source', 'section': 'Required Inputs'}, 'input_vault_key': {'type': 'string', 'label': 'Input Vault key', 'required': False, 'tab': 'Source', 'section': 'Required Inputs', 'vault_type': 'string', 'visible_when': {'input_source': 'Vault'}}, 'input': {'type': 'multiline', 'label': 'Question', 'height': 5, 'description': 'One reply, no tools. Uses your Hermes account; no dollar cap.', 'tab': 'Parameters', 'visible_when': {'input_source': 'Configured'}}, 'folder': {'type': 'string', 'label': 'Folder', 'required': True, 'placeholder': 'A folder allowed in Options', 'tab': 'Parameters'}, 'timeout': {'type': 'integer', 'label': 'Stop after (seconds)', 'min': 10, 'max': 300, 'tab': 'Parameters'}}
    ui_hints: ClassVar[Dict[str, Any]] = {}
    error_definitions: ClassVar[List[Dict[str, Any]]] = [{'code': 'not_installed', 'description': 'Hermes is not installed.', 'retryable': False}, {'code': 'unsupported_runtime', 'description': "This Hermes version can't run with these limits.", 'retryable': False}, {'code': 'auth_failed', 'description': 'Sign in to Hermes first.', 'retryable': False}, {'code': 'folder_missing', 'description': 'Choose an existing folder.', 'retryable': False}, {'code': 'not_allowed', 'description': 'This folder is not allowed in Options.', 'retryable': False}, {'code': 'text_too_long', 'description': 'The question is too long.', 'retryable': False}, {'code': 'timed_out', 'description': 'Stopped after the time limit.', 'retryable': False}, {'code': 'turn_limit', 'description': 'Stopped after the turn limit.', 'retryable': False}, {'code': 'permission_denied', 'description': 'Hermes requested a tool it was not given.', 'retryable': False}, {'code': 'agent_failed', 'description': 'Hermes could not finish.', 'retryable': False}, {'code': 'invalid_response', 'description': 'No complete answer was returned.', 'retryable': False}, {'code': 'record_failed', 'description': 'The run record could not be saved.', 'retryable': False}, {'code': 'cleanup_failed', 'description': 'The agent did not stop cleanly.', 'retryable': False}]

    async def execute(self, context: NodeContext) -> None:
        from ...integrations import hermes_ask
        from ...system_access import checked_path
        from ...node_errors import NodeError
        timeout = self.config.get("timeout")
        if type(timeout) is not int or not 10 <= timeout <= 300:
            context.signal_error(NodeError("node_error", "Choose 10 to 300 seconds"))
            return
        for enabled, field in (("vault_write", "vault_write_key"),
                               ("details_vault_write", "details_vault_key")):
            if self.config.get(enabled) and not str(self.config.get(field) or "").strip():
                context.signal_error(NodeError("node_error", "Enter a Vault output key"))
                return
        if (self.config.get("vault_write") and self.config.get("details_vault_write")
                and self.config.get("vault_write_key", "").strip() == self.config.get("details_vault_key", "").strip()):
            context.signal_error(NodeError("node_error", "Answer and Run details need different Vault keys"))
            return
        source = self.config.get("input_source")
        question = (context.inputs.get("input") if source == "Upstream payload" else
                    context.memory_bank.read_persistent(self.config.get("input_vault_key", "")) if source == "Vault" else
                    self.config.get("input") if source == "Configured" else None)
        if not isinstance(question, str) or not question.strip():
            context.signal_error(NodeError("node_error", "Choose a non-empty question"))
            return
        if len(question) > hermes_ask.MAX_QUESTION:
            context.signal_error(hermes_ask.failure("text_too_long"))
            return
        try:
            folder = checked_path(self.config.get("folder"), context.get_setting)
            if not folder.is_dir():
                raise hermes_ask.failure("folder_missing")
            answer, details = await hermes_ask.ask(context, question, folder, timeout)
        except NodeError as exc:
            context.signal_error(exc)
            return
        if self.config.get("details_vault_write"):
            context.memory_bank.store_persistent(self.config["details_vault_key"].strip(), details, type_tag="var")
        if self.config.get("vault_write"):
            context.memory_bank.store_persistent(self.config["vault_write_key"].strip(), answer, type_tag="string")
        forwarding = self.config.get("dead_drop_passthrough")
        payload = context.inputs.get("input") if forwarding else answer
        context.signal_done({"data": {"default": payload}
                             if forwarding or self.config.get("transient_output", True) else {}})
